import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import { EXAMPLE, envFiles, scan } from "./files";

export const DECLARATION = "env.d.ts";

interface Entry {
  doc?: string;
  section?: string;
  required: boolean;
}

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/;

function jsdoc(entry: Entry): string[] {
  const lines = entry.doc ? entry.doc.split("\n") : [];

  if (entry.section) lines.push(...(lines.length ? [""] : []), `@category ${entry.section}`);
  if (!lines.length) return [];

  return ["    /**", ...lines.map(line => `     *${line && " "}${line.replaceAll("*/", "*\\/")}`), "     */"];
}

export function declaration(root: string): string | undefined {
  const names = envFiles(root);

  if (!names.length) return;

  const keys = new Map<string, Entry>();

  for (const file of names)
    for (const { name, doc, section } of scan(readFileSync(join(root, file), "utf8"))) {
      const known = keys.get(name);
      const required = file === EXAMPLE || file === ".env";

      keys.set(name, {
        doc: known?.doc ?? doc,
        section: known ? known.section : section,
        required: !!known?.required || required,
      });
    }

  const sections = [...new Set([...keys.values()].map(entry => entry.section))];
  const body = sections.flatMap(section => {
    const members = [...keys].filter(([, entry]) => entry.section === section);
    const lines = members.flatMap(([name, entry]) => [
      ...jsdoc(entry),
      `    readonly ${IDENTIFIER.test(name) ? name : JSON.stringify(name)}${entry.required ? "" : "?"}: string;`,
    ]);

    return section ? [`    // ${section}`, "", ...lines, ""] : [...lines, ""];
  });

  return [
    `// Generated by \`expressive env sync\` from ${names.join(", ")} - key names and comments, no values.`,
    `import "@expressive/env";`,
    "",
    `declare module "@expressive/env" {`,
    "  interface Env {",
    ...body.slice(0, -1),
    "  }",
    "}",
    "",
  ].join("\n");
}

export function write(root: string): "written" | "current" | undefined {
  const text = declaration(root);
  const path = join(root, DECLARATION);

  if (text === undefined) return;
  if (existsSync(path) && readFileSync(path, "utf8") === text) return "current";

  writeFileSync(path, text);
  return "written";
}

export function stale(root: string): boolean {
  const text = declaration(root);
  const path = join(root, DECLARATION);

  return text !== undefined && (!existsSync(path) || readFileSync(path, "utf8") !== text);
}
